// Comprehensive translations for all pages supporting 8 languages
// Languages: en, ar, ru, uk, ro, pl, it, tr

export type SupportedLanguage = "en" | "ar" | "ru" | "uk" | "ro" | "pl" | "it" | "tr";

// Helper function to get text by language
export function getText<T extends Record<SupportedLanguage, string> | undefined | null>(
  translations: T,
  language: string
): string {
  if (!translations) return "";
  const lang = language as SupportedLanguage;
  return translations[lang] || translations.en || "";
}

